  'suggestions.cible_decision.suggestion_inconnue': 'Suggestion inconnue : « {cle} ».',
  'suggestions.comprendre.1_creer_gamme_equipement': { one: '<b>S1 · Créer une gamme</b> : équipement suivi sans aucune gamme active, au moins {n} panne de même cause sur la période.', other: '<b>S1 · Créer une gamme</b> : équipement suivi sans aucune gamme active, au moins {n} pannes de même cause sur la période.' },
  'suggestions.comprendre.2_revoir_preventif_equipement': { one: '<b>S2 · Revoir le préventif</b> : équipement dont une gamme suivie a déjà eu une visite ; au moins {n} panne de même cause sur la période, après la première visite. À examiner : la gamme ne dit pas quelles pannes elle prévient.', other: '<b>S2 · Revoir le préventif</b> : équipement dont une gamme suivie a déjà eu une visite ; au moins {n} pannes de même cause sur la période, après la première visite. À examiner : la gamme ne dit pas quelles pannes elle prévient.' },
  'suggestions.comprendre.3_anomalies_repetees_gamme': '<b>S3 · Anomalies répétées</b> : gamme suivie avec une anomalie à au moins 2 des 4 dernières visites.',
  'suggestions.comprendre.4_allonger_gamme_depuis_format_2': { one: '<b>S4 · Allonger une gamme</b> : gamme suivie d\'un équipement de criticité B ou C (jamais A) ; au moins {n} visite de suite sans anomalie (comptées depuis le passage au format 2, le {date}), et aucune panne de l\'équipement depuis la première de ces visites. Les contrôles réglementaires ne sont jamais suggérés.', other: '<b>S4 · Allonger une gamme</b> : gamme suivie d\'un équipement de criticité B ou C (jamais A) ; au moins {n} visites de suite sans anomalie (comptées depuis le passage au format 2, le {date}), et aucune panne de l\'équipement depuis la première de ces visites. Les contrôles réglementaires ne sont jamais suggérés.' },
  'suggestions.comprendre.4_allonger_gamme_gamme': { one: '<b>S4 · Allonger une gamme</b> : gamme suivie d\'un équipement de criticité B ou C (jamais A) ; au moins {n} visite de suite sans anomalie, et aucune panne de l\'équipement depuis la première de ces visites. Les contrôles réglementaires ne sont jamais suggérés.', other: '<b>S4 · Allonger une gamme</b> : gamme suivie d\'un équipement de criticité B ou C (jamais A) ; au moins {n} visites de suite sans anomalie, et aucune panne de l\'équipement depuis la première de ces visites. Les contrôles réglementaires ne sont jamais suggérés.' },
  'suggestions.comprendre.apres_decision_ignoree_traitee': '<b>Après une décision</b> (ignorée ou traitée), seuls les faits postérieurs comptent : la suggestion revient s\'ils atteignent de nouveau le seuil.',
  'suggestions.comprendre.comprendre_suggestions': 'Comprendre les suggestions',
  'suggestions.comprendre.date_ot_fin_travaux': '<b>Date d\'un OT</b> : fin des travaux, sinon clôture technique, sinon création.',
  'suggestions.comprendre.definitions': 'Définitions',
  'suggestions.comprendre.equipement_suivi_actif_pas': '<b>Équipement suivi</b> : actif et pas au rebut. <b>Gamme suivie</b> : active, par date ou au compteur (jamais au seuil), d\'un équipement suivi.',
  'suggestions.comprendre.intervalle_median_ecart_milieu': '<b>Intervalle médian</b> : l\'écart du milieu, en jours, entre deux pannes qui se suivent (la moitié des écarts sont plus courts).',
  'suggestions.comprendre.ordre_cartes_2_3': 'Ordre des cartes : S2, S3, S1 puis S4 ; puis criticité A, B, C ; puis nombre de faits. Les seuils se règlent dans Paramètres (section « Suggestions de préventif »).',
  'suggestions.comprendre.panne_meme_cause_ot': '<b>Panne de même cause</b> : OT correctif (immédiat ou différé) clôturé, avec le même code cause (toutes les causes, « Autre cause » comprise).',
  'suggestions.comprendre.periode_derniers_mois_aujourd': { one: '<b>Période</b> : les {n} derniers mois, du {debutFenetre} à aujourd\'hui.', other: '<b>Période</b> : les {n} derniers mois, du {debutFenetre} à aujourd\'hui.' },
  'suggestions.comprendre.prevo_modifie_jamais_gamme': '<b>Prévo ne modifie jamais une gamme tout seul.</b> Une suggestion n\'écrit rien : vous décidez. « Créer la gamme » et « Ouvrir la gamme » mènent aux écrans du préventif ; la suggestion est marquée traitée quand vous créez ou modifiez la gamme. « Ignorer… » demande un motif. Chaque décision est inscrite au journal (onglet « Décisions »).',
